using System;using System.Linq;using System.IO;using System.Text;using System.Globalization;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class LengthInput {
 public double Db=20,Fy=420,Fc=21,Cover=40,Spacing=40,Ktr=0,AsRatio=1,Spliced=100,Round=5,Straight=0;public bool Top,Epoxy,Lightweight;public bool Simplified=true;
}
class LengthResult {
 public double LapA,LapB,BondRatio,PsiT,PsiE,PsiS,Lambda,LdRaw,Ld,Ldh,Ldc,Lap,CompressionLap,MainInside,TieInside,Tail90,Tail180,Tail135,Cut90,Cut180,Cut135;public string LapClass;
}
static class RebarLengths {
 public static LengthResult Calculate(LengthInput i){
  foreach(double x in new[]{i.Db,i.Fy,i.Fc,i.Cover,i.Spacing,i.Ktr,i.AsRatio,i.Spliced,i.Round,i.Straight})if(double.IsNaN(x)||double.IsInfinity(x))throw new Exception("All inputs must be finite numbers.");
  if(i.Db<10||i.Db>36||i.Fy<200||i.Fy>420||i.Fc<17||i.Fc>70||i.Cover<0||i.Spacing<=0||i.Ktr<0||i.AsRatio<=0||i.Spliced<=0||i.Spliced>100||i.Round<1||i.Straight<0)throw new Exception("Check input ranges: db10-36mm,fy200-420MPa,fc17-70MPa; positive spacing, splice percent and rounding.");
  var r=new LengthResult();r.Lambda=i.Lightweight?.75:1;r.PsiT=i.Top?1.3:1;r.PsiE=i.Epoxy?(i.Cover<3*i.Db||i.Spacing<6*i.Db?1.5:1.2):1;r.PsiS=i.Db<=19?.8:1;
  double cb=Math.Min(i.Cover+i.Db/2,(i.Spacing+i.Db)/2),sqrt=Math.Min(Math.Sqrt(i.Fc),8.3);r.BondRatio=Math.Min((cb+i.Ktr)/i.Db,2.5);if(r.BondRatio<=0)throw new Exception("Invalid bond ratio.");
  if(i.Simplified&&i.Db>20&&i.Db<25)throw new Exception("The sample method uses PNS sizes <=20mm or >=25mm.");r.LdRaw=i.Simplified?i.Fy*Math.Min(r.PsiT*r.PsiE,1.7)*i.Db/((i.Db<=20?1.4:1.1)*r.Lambda*sqrt):i.Fy/(1.1*r.Lambda*sqrt)*Math.Min(r.PsiT*r.PsiE,1.7)*r.PsiS/r.BondRatio*i.Db;r.Ld=Math.Max(300,r.LdRaw);
  r.LapClass=i.AsRatio>=2&&i.Spliced<=50?"A":"B";r.LapA=Math.Max(300,r.LdRaw);r.LapB=Math.Max(300,1.3*r.LdRaw);r.Lap=r.LapClass=="A"?r.LapA:r.LapB;
  r.Ldh=Math.Max(Math.Max((i.Simplified?1.0/4.17:.24)*i.Fy*(i.Epoxy?1.2:1)/(r.Lambda*sqrt)*i.Db,8*i.Db),150);
  r.Ldc=Math.Max(Math.Max(.24*i.Fy/(r.Lambda*sqrt)*i.Db,.043*i.Fy*i.Db),200);
  r.CompressionLap=Math.Max(.071*i.Fy*i.Db,300)*(i.Fc<21?4.0/3:1);
  r.MainInside=HookGeometry.Inside((int)i.Db,false);r.TieInside=i.Db<=25?HookGeometry.Inside((int)i.Db,true):0;r.Tail90=12*i.Db;r.Tail180=Math.Max(4*i.Db,65);r.Tail135=Math.Max(6*i.Db,75);
  double mainRadius=(r.MainInside+i.Db)/2;r.Cut90=i.Straight+Math.PI/2*mainRadius+r.Tail90;r.Cut180=i.Straight+Math.PI*mainRadius+r.Tail180;r.Cut135=r.TieInside==0?0:i.Straight+3*Math.PI/4*((r.TieInside+i.Db)/2)+r.Tail135;return r;
 }
 public static double Up(double value,double step){return Math.Ceiling(value/step-1e-10)*step;}
 public static string Report(LengthInput i){var r=Calculate(i);var b=new StringBuilder();Func<double,string> n=x=>x.ToString("0.00",CultureInfo.InvariantCulture);Func<double,string> adopt=x=>n(Up(x,i.Round));double sqrt=Math.Min(Math.Sqrt(i.Fc),8.3),cb=Math.Min(i.Cover+i.Db/2,(i.Spacing+i.Db)/2),psi=Math.Min(r.PsiT*r.PsiE,1.7),k=i.Db<=20?1.4:1.1;
 b.AppendLine("SPLICE, DEVELOPMENT & HOOKS - COMPLETE CALCULATION");b.AppendLine("Selected db="+n(i.Db)+"mm | "+(i.Top?"TOP":"OTHER")+" bar | fy="+n(i.Fy)+"MPa | fc="+n(i.Fc)+"MPa");b.AppendLine("## 01  INPUTS & MODIFICATION FACTORS");b.AppendLine("Method: "+(i.Simplified?"NSCP425.4.2.2 simplified OTHER CASES (supplied sample)":"ACI318M-14 general bond-ratio equation"));b.AppendLine("Clear cover TO BAR="+n(i.Cover)+"mm; clear spacing="+n(i.Spacing)+"mm; Ktr="+n(i.Ktr)+"mm.");b.AppendLine("lambda="+n(r.Lambda)+"; psi_t="+n(r.PsiT)+"; psi_e="+n(r.PsiE)+"; psi_s="+n(r.PsiS)+".");b.AppendLine("psi_t*psi_e = "+n(r.PsiT*r.PsiE)+"; cap1.70 -> USE "+n(psi)+".");b.AppendLine("sqrt(fc)="+n(Math.Sqrt(i.Fc))+"; cap8.30 -> USE "+n(sqrt)+".");b.AppendLine("cb=min(cover+db/2,(spacing+db)/2)=min("+n(i.Cover+i.Db/2)+","+n((i.Spacing+i.Db)/2)+")="+n(cb)+"mm.");b.AppendLine("Bond ratio=min((cb+Ktr)/db,2.50)=min("+n((cb+i.Ktr)/i.Db)+",2.50)="+n(r.BondRatio)+".");b.AppendLine("Bond ratio and psi_s enter the GENERAL method; simplified method uses k="+n(k)+".");b.AppendLine();
 b.AppendLine("## 02  TENSION DEVELOPMENT Ld");if(i.Simplified){b.AppendLine("Ld raw=fy*capped(psi_t*psi_e)*db/(k*lambda*sqrt(fc)).");b.AppendLine("      ="+n(i.Fy)+"*"+n(psi)+"*"+n(i.Db)+"/("+n(k)+"*"+n(r.Lambda)+"*"+n(sqrt)+")="+n(r.LdRaw)+"mm.");}else{b.AppendLine("Ld raw=fy*capped(psi_t*psi_e)*psi_s*db/(1.10*lambda*sqrt(fc)*bond ratio).");b.AppendLine("      ="+n(i.Fy)+"*"+n(psi)+"*"+n(r.PsiS)+"*"+n(i.Db)+"/(1.10*"+n(r.Lambda)+"*"+n(sqrt)+"*"+n(r.BondRatio)+")="+n(r.LdRaw)+"mm.");}b.AppendLine("Ld=max(raw,300)=max("+n(r.LdRaw)+",300.00)="+n(r.Ld)+" -> USE "+adopt(r.Ld)+"mm.");b.AppendLine();
 b.AppendLine("## 03  TENSION LAP SPLICES - CLASS A / B");b.AppendLine("As provided/required="+n(i.AsRatio)+"; bars spliced="+n(i.Spliced)+"%.");b.AppendLine("Class A requires As ratio>=2.00 AND <=50.00% bars spliced; otherwise Class B.");b.AppendLine("Lap A=max(1.00*RAW Ld,300)=max("+n(r.LdRaw)+",300.00)="+n(r.LapA)+" -> USE "+adopt(r.LapA)+"mm.");b.AppendLine("Lap B=max(1.30*RAW Ld,300)=max("+n(1.3*r.LdRaw)+",300.00)="+n(r.LapB)+" -> USE "+adopt(r.LapB)+"mm.");b.AppendLine("GOVERNING: CLASS "+r.LapClass+" -> "+adopt(r.Lap)+"mm. Round only after the raw-length check.");var opposite=new LengthInput{Db=i.Db,Fy=i.Fy,Fc=i.Fc,Cover=i.Cover,Spacing=i.Spacing,Ktr=i.Ktr,AsRatio=i.AsRatio,Spliced=i.Spliced,Round=i.Round,Top=!i.Top,Epoxy=i.Epoxy,Lightweight=i.Lightweight,Simplified=i.Simplified};var other=Calculate(opposite);b.AppendLine((i.Top?"OTHER":"TOP")+"-position check: rawLd="+n(other.LdRaw)+"; USE Ld="+adopt(other.Ld)+", LapA="+adopt(other.LapA)+", LapB="+adopt(other.LapB)+"mm.");b.AppendLine();
 b.AppendLine("## 04  COMPRESSION DEVELOPMENT & SPLICE");double c1=.24*i.Fy/(r.Lambda*sqrt)*i.Db,c2=.043*i.Fy*i.Db,cLap=.071*i.Fy*i.Db,mult=i.Fc<21?4.0/3:1;
 b.AppendLine("Ldc=max(0.24*fy*db/(lambda*sqrt(fc)),0.043*fy*db,200).");b.AppendLine("   =max("+n(c1)+","+n(c2)+",200.00)="+n(r.Ldc)+" -> USE "+adopt(r.Ldc)+"mm.");b.AppendLine("Compression lap=max(0.071*fy*db,300)*low-fc factor; valid here for fy<=420MPa.");b.AppendLine("   =max(0.071*"+n(i.Fy)+"*"+n(i.Db)+",300.00)*"+n(mult));b.AppendLine("   =max("+n(cLap)+",300.00)*"+n(mult)+"="+n(r.CompressionLap)+" -> USE "+adopt(r.CompressionLap)+"mm.");b.AppendLine("Low-fc factor=4/3 when fc<21MPa, otherwise1.00.");b.AppendLine();b.AppendLine("All calculated lengths are mm. USE values round UP to "+n(i.Round)+"mm; display2decimals.");b.AppendLine("Full precision is retained internally; displayed substitutions are rounded for readability.");
 b.AppendLine("\f");b.AppendLine("HOOK DEVELOPMENT, STANDARD GEOMETRY & CUTTING LENGTH");b.AppendLine("db="+n(i.Db)+"mm | fy="+n(i.Fy)+"MPa | fc="+n(i.Fc)+"MPa | "+(i.Epoxy?"EPOXY":"UNCOATED"));b.AppendLine("## 05  HOOKED TENSION DEVELOPMENT Ldh");double coef=i.Simplified?1.0/4.17:.24,epoxy=i.Epoxy?1.2:1,rawHook=coef*i.Fy*epoxy/(r.Lambda*sqrt)*i.Db;
 b.AppendLine("Ldh raw="+(i.Simplified?"(1/4.17)":"0.24")+"*fy*hook epoxy factor*db/(lambda*sqrt(fc)).");b.AppendLine("       ="+(i.Simplified?"(1/4.17)":"0.24")+"*"+n(i.Fy)+"*"+n(epoxy)+"*"+n(i.Db)+"/("+n(r.Lambda)+"*"+n(sqrt)+")="+n(rawHook)+"mm.");b.AppendLine("Ldh=max(raw,8db,150)=max("+n(rawHook)+","+n(8*i.Db)+",150.00)="+n(r.Ldh)+"mm.");b.AppendLine("ADOPT Ldh="+adopt(r.Ldh)+"mm. No cover/confinement reduction applied.");b.AppendLine("Ldh is embedment; it is not hook tail length or centerline cutting length.");b.AppendLine();b.AppendLine("## 06  MINIMUM BENDS & HOOK TAILS");b.AppendLine("Main inside bend ID="+(i.Db<=25?"6db":"8db")+"="+n(r.MainInside)+"mm.");b.AppendLine("Main centerline radius R=(ID+db)/2=("+n(r.MainInside)+"+"+n(i.Db)+")/2="+n((r.MainInside+i.Db)/2)+"mm.");b.AppendLine("90deg main tail=12db=12*"+n(i.Db)+"="+n(r.Tail90)+"mm.");b.AppendLine("180deg main tail=max(4db,65)=max("+n(4*i.Db)+",65.00)="+n(r.Tail180)+"mm.");b.AppendLine("135deg seismic tie tail=max(6db,75)=max("+n(6*i.Db)+",75.00)="+n(r.Tail135)+"mm.");b.AppendLine("Entered straight TANGENT leg S="+n(i.Straight)+"mm (one hook only).");b.AppendLine();b.AppendLine("## 07  CENTERLINE CUT = STRAIGHT + ARC + TAIL");Action<string,double,double,double> hook=(name,angle,radius,tail)=>{double arc=angle*Math.PI/180*radius,cut=i.Straight+arc+tail;b.AppendLine(name+": arc=angle*pi*R/180="+n(angle)+"*pi*"+n(radius)+"/180="+n(arc)+"mm.");b.AppendLine("  Cut="+n(i.Straight)+"+"+n(arc)+"+"+n(tail)+"="+n(cut)+" -> USE "+adopt(cut)+"mm.");};double radiusMain=(r.MainInside+i.Db)/2;hook("90deg MAIN",90,radiusMain,r.Tail90);hook("180deg MAIN",180,radiusMain,r.Tail180);
 if(r.TieInside>0){double radiusTie=(r.TieInside+i.Db)/2;b.AppendLine("Tie inside bend ID="+n(r.TieInside)+"mm; tie centerline R="+n(radiusTie)+"mm.");hook("135deg SEISMIC TIE",135,radiusTie,r.Tail135);b.AppendLine();b.AppendLine("## 08  ADDITIONAL-LEG90/130 CUSTOM DETAIL (ESTIMATOR)");double tail90=i.Db<=16?Math.Max(6*i.Db,75):12*i.Db,arc90=90*Math.PI/180*radiusTie,arc130=130*Math.PI/180*radiusTie;b.AppendLine("Requested crosstie: one90deg + oneCUSTOM130deg hook, using the tie bend radius.");b.AppendLine("90deg arc="+n(arc90)+"mm; tail="+n(tail90)+"mm. 130deg arc="+n(arc130)+"mm; tail="+n(r.Tail135)+"mm.");b.AppendLine("Cut/body relation = depth centerline -2R + arc90 + arc130 + tail90 + tail130.");b.AppendLine("                 = depth centerline + "+n(-2*radiusTie+arc90+arc130+tail90+r.Tail135)+"mm.");b.AppendLine("Beam depth comes from DXF in Estimator.130deg is a custom project detail, not the standard135deg hook.");}else b.AppendLine("Tie geometry above25mm is outside the supported standard tie-bend model; project detail required.");b.AppendLine();b.AppendLine("## 09  SCOPE & REFERENCES");b.AppendLine("Selected NSCP2015 / ACI318M-14 Ch25 basis: hooks25.3; tension25.4.2; hooked development25.4.3;");b.AppendLine("compression25.4.9; tension laps25.5.2; compression laps25.5.5. Simplified mode follows supplied sample.");b.AppendLine("Same-size individual bars, db10-36mm, fy200-420MPa. No bundled-bar, excess-steel or confinement reduction.");b.AppendLine("Verify actual splice locations, seismic restrictions and support geometry. Estimator excludes entered S.");b.AppendLine("Calculations retain full precision; outputs display2decimals and design lengths round UP to "+n(i.Round)+"mm.");return b.ToString();
 }
}
