 static FlowLayoutPanel Group(FlowLayoutPanel host,string name,int height){host.Controls.Add(new Label{Text=name,UseMnemonic=false,Width=500,Height=34,TextAlign=ContentAlignment.BottomLeft,Font=ModernUi.Strong,ForeColor=PowTheme.Teal,Margin=new Padding(0,6,0,4)});return host;}
 static Panel Row(FlowLayoutPanel p,string label,Control input){var row=new Panel{Width=500,Height=36,Margin=new Padding(0,0,0,2)};row.Controls.Add(new Label{Text=label,UseMnemonic=false,Location=new Point(0,8),Size=new Size(276,22),ForeColor=PowTheme.Ink});input.Location=new Point(284,4);input.Width=212;row.Controls.Add(input);p.Controls.Add(row);return row;}
 static NumericUpDown Number(FlowLayoutPanel p,string label,decimal min,decimal max,decimal value,int digits){var n=new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=digits,ThousandsSeparator=true,TextAlign=HorizontalAlignment.Right};Row(p,label,n);return n;}
 static ComboBox Select(FlowLayoutPanel p,string label,string[] items){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,DropDownWidth=320};c.Items.AddRange(items);c.SelectedIndex=0;Row(p,label,c);return c;}
 static CheckBox Check(FlowLayoutPanel p,string label){var c=new CheckBox{Text=label,Width=496,Height=30,Margin=new Padding(0,2,0,2)};p.Controls.Add(c);return c;}
 static DataGridView Table(string[] names,bool fill){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,AutoSizeColumnsMode=fill?DataGridViewAutoSizeColumnsMode.Fill:DataGridViewAutoSizeColumnsMode.None,SelectionMode=DataGridViewSelectionMode.CellSelect,MultiSelect=false,EnableHeadersVisualStyles=false,ColumnHeadersHeight=48,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(232,239,247);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.FromArgb(23,43,67);g.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",9,FontStyle.Bold);g.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;g.DefaultCellStyle.Font=new Font("Segoe UI",9);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(218,232,247);g.DefaultCellStyle.SelectionForeColor=Color.FromArgb(23,43,67);g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(247,249,252);g.RowTemplate.Height=34;foreach(string name in names)g.Columns.Add(name,name);if(fill){g.Columns[0].FillWeight=165;g.Columns[g.Columns.Count-1].FillWeight=145;}else foreach(DataGridViewColumn col in g.Columns){col.Width=83;if(col.Index>0)col.DefaultCellStyle.Format="N2";}GridAppearance.Apply(g);return g;}
 LengthInput Input(){return new LengthInput{Simplified=method.SelectedIndex==0,Db=(double)dia.Value,Fy=(double)(dia.Value<=12?fySmall.Value:fy.Value),Fc=(double)fc.Value,Cover=(double)cover.Value,Spacing=(double)spacing.Value,Ktr=(double)ktr.Value,AsRatio=(double)asRatio.Value,Spliced=(double)spliced.Value,Round=(double)round.Value,Straight=(double)straight.Value,Top=top.Checked,Epoxy=epoxy.Checked,Lightweight=light.Checked};}
 public LengthConfiguration Configuration(){var c=new LengthConfiguration{Name=configName.Text.Trim(),Input=Input(),FySmall=(double)fySmall.Value,FyLarge=(double)fy.Value,GradeSmall=gradeSmall.SelectedIndex==0?40:60,GradeLarge=grade.SelectedIndex==0?60:40};c.Validate();return c;}
 public void ApplyConfiguration(LengthConfiguration c){c.Validate();applying=true;try{method.SelectedIndex=c.Input.Simplified?0:1;configName.Text=c.Name;gradeSmall.SelectedIndex=c.GradeSmall==40?0:1;grade.SelectedIndex=c.GradeLarge==60?0:1;fySmall.Value=(decimal)c.FySmall;fy.Value=(decimal)c.FyLarge;if(c.Input.Fc==21||c.Input.Fc==28||c.Input.Fc==35)concrete.SelectedIndex=c.Input.Fc==21?0:c.Input.Fc==28?1:2;fc.Value=(decimal)c.Input.Fc;dia.Value=(decimal)c.Input.Db;top.Checked=c.Input.Top;straight.Value=(decimal)c.Input.Straight;cover.Value=(decimal)c.Input.Cover;spacing.Value=(decimal)c.Input.Spacing;ktr.Value=(decimal)c.Input.Ktr;asRatio.Value=(decimal)c.Input.AsRatio;spliced.Value=(decimal)c.Input.Spliced;round.Value=(decimal)c.Input.Round;epoxy.Checked=c.Input.Epoxy;light.Checked=c.Input.Lightweight;}finally{applying=false;}UpdateResult();}
 public string Sheet(){var c=Configuration();var b=new StringBuilder(c.Review());b.AppendLine("Full numeric checks: "+"all 8 diameters"+". Each includes development, splice and hook calculations.");foreach(int diameter in new[]{10,12,16,20,25,28,32,36}){var i=c.ForDiameter(diameter,top.Checked);i.Straight=(double)straight.Value;b.Append("\f\n"+RebarLengths.Report(i));}return b.ToString();}
 void UpdateResult(){if(applying||output==null)return;try{var i=Input();var r=RebarLengths.Calculate(i);headline.Text="Diameter "+i.Db+" mm  |  "+(i.Top?"TOP BAR":"OTHER BAR")+"  |  Tension lap: Class "+r.LapClass+"\nfy "+i.Fy+" MPa  /  f'c "+i.Fc+" MPa  /  round UP "+i.Round+" mm";results.Rows.Clear();Action<string,double,string> add=(name,v,basis)=>results.Rows.Add(name,v.ToString("0.00"),RebarLengths.Up(v,i.Round).ToString("0.00"),basis);add("Development - tension Ld",r.Ld,"min 300mm");add("Development - hooked Ldh",r.Ldh,"min max(8db,150)");add("Development - compression",r.Ldc,"min 200mm");add("Splice - tension Class A",r.LapA,"As>=2 & <=50% spliced");add("Splice - tension Class B",r.LapB,"1.3 x raw Ld");add("Splice - compression",r.CompressionLap,"same-size bars");hooks.Rows.Clear();hooks.Rows.Add("90deg main",r.MainInside.ToString("0.00"),r.Tail90.ToString("0.00"),RebarLengths.Up(r.Cut90,i.Round).ToString("0.00"));hooks.Rows.Add("180deg main",r.MainInside.ToString("0.00"),r.Tail180.ToString("0.00"),RebarLengths.Up(r.Cut180,i.Round).ToString("0.00"));hooks.Rows.Add("135deg seismic tie",r.TieInside==0?"N/A":r.TieInside.ToString("0.00"),r.Tail135.ToString("0.00"),r.Cut135==0?"N/A":RebarLengths.Up(r.Cut135,i.Round).ToString("0.00"));summary.Rows.Clear();var cfg=Configuration();foreach(int d in new[]{10,12,16,20,25,28,32,36}){var b=cfg.Values(d,false);var t=cfg.Values(d,true);summary.Rows.Add(d,cfg.Rounded(b.Ld),cfg.Rounded(b.Ldh),cfg.Rounded(b.LapA),cfg.Rounded(b.LapB),cfg.Rounded(t.Ld),cfg.Rounded(t.LapA),cfg.Rounded(t.LapB),cfg.Rounded(b.Ldc),cfg.Rounded(b.CompressionLap));}output.Text=Sheet().Replace("## ","");status.Text="Beam Estimator automatically selects saved values by concrete strength and steel grades.\n"+(i.Simplified?"Simplified method: bond-ratio inputs do not reduce Ld.":"General method: cover, spacing and Ktr determine the capped bond ratio.");results.Rows[r.LapClass=="A"?3:4].DefaultCellStyle.BackColor=Color.FromArgb(221,241,232);results.ClearSelection();hooks.ClearSelection();summary.ClearSelection();}catch(Exception ex){results.Rows.Clear();hooks.Rows.Clear();summary.Rows.Clear();headline.Text="Check calculation inputs";output.Text=ex.Message;status.Text=ex.Message;}}
}

